from lesson_helpers import *
from lesson_figures import figure,CSS
titles=['Définition','Épidémiologie','Physiopathologie','Démarche clinique','Anamnèse','Examen clinique','Syndromes','Diagnostic positif','Explorations','Arbre diagnostique et différentiels','Prise en charge','Prévention, suivi et pronostic','Points clés','Pièges']
a='''<template id="ch-G25"><div class="chap"><div class="chap-head"><div class="code">G25 · Mouvements anormaux · S08 · CIM-10-GM suisse 2024</div><h1>Autres syndromes extrapyramidaux et troubles de la motricité</h1><span class="status">Sol-Neurologie-G25 · Auto-relecture IA documentée · Sans validation médicale humaine</span></div><div class="tabs ui" role="tablist"><button role="tab" aria-controls="pA" data-p="pA" aria-selected="true">⚕ Pathologie et prise en charge</button><button role="tab" aria-controls="pE" data-p="pE" aria-selected="false">🔬 Examens complémentaires</button><button role="tab" aria-controls="pS" data-p="pS" aria-selected="false">⚛ Sciences fondamentales spécialisées</button><button role="tab" aria-controls="pP" data-p="pP" aria-selected="false">💊 Pharmacologie</button></div>'''+CSS+'''<div class="panel" id="pA"><nav class="toc ui"><b>Plan monographique</b><ol>'''+''.join('<li><a href="#g25-'+str(i)+'">'+t+'</a></li>' for i,t in enumerate(titles,1))+'''</ol></nav><div class="chap-body" data-semiology-clinical="G25">'''
a+=sec('question','Un mouvement anormal : quelle description change la décision ?', '''<p><b>Situations fictives originales.</b> Une personne renverse son verre quand elle l’approche de la bouche. Une autre lâche brusquement des objets et devient confuse après une modification de traitement. Une troisième doit marcher le soir pour soulager une gêne des jambes. Une quatrième développe une raideur du tronc et des spasmes au bruit. Ces tableaux demandent des questions, des examens et des traitements différents.</p><p>La priorité est de reconnaître une urgence, de décrire le mouvement et de chercher sa cause. Le nom du chapitre rassemble plusieurs syndromes ; il ne constitue pas une maladie unique. L’examen fédéral mobilise cette démarche clinique : description, hypothèses, décision utile et communication des limites.</p>'''+key('Décrire le phénomène, rechercher une cause traitable, puis choisir un traitement adapté à la personne et à la formulation.'),('CH-PROFILES','CH-MEBEKO','EU-TREMOR-PHENO','EU-MYO-DX','EU-RLS-DX','EU-SPS-DX'))
a+=sec(1,'1. Définition : plusieurs phénomènes, des frontières précises', '''<p>Un '''+w('definition','trouble du mouvement')+''' se décrit avant de recevoir une étiquette étiologique. Le '''+w('phenotype','phénotype')+''' précise rythme, durée, distribution, conditions de survenue et signes associés. Un tremblement oscille ; une myoclonie est une secousse brève ou une interruption de contraction ; une chorée est irrégulière et imprévisible ; un tic peut s’accompagner d’un besoin prémonitoire et d’une suppression transitoire.</p>'''+table(['OFS 2024','Portée du sous-code'],[['G25.0','Tremblement essentiel ou familial ; tremblement sans précision R25.1 exclu'],['G25.1 / G25.2','Tremblement médicamenteux / autres tremblements précisés, dont intention'],['G25.3','Myoclonies ; épilepsie myoclonique G40.- et myokymie faciale G51.4 exclues'],['G25.4 / G25.5','Chorée médicamenteuse / autres chorées ; Huntington G10 et Sydenham I02.- exclus de G25.5'],['G25.6','Tics médicamenteux ou autres organiques ; Tourette F95.2 et tic sans précision F95.9 exclus'],['G25.80 / G25.81','Mouvements périodiques des jambes pendant le sommeil / syndrome des jambes sans repos'],['G25.88 / G25.9','Autres, dont akathisie et syndrome de la personne raide / sans précision']])+'''<p>G25.8 est subdivisé dans cette version suisse ; aucun G25.82 emprunté à une autre nomenclature n’est ajouté. Une cause médicamenteuse peut demander un code externe supplémentaire selon la note. La conclusion clinique et l’imputabilité précèdent ce choix ; une indication de médicament ne détermine pas à elle seule le code.</p>''',('CH-CIM','CH-CIM-BOUND','EU-TREMOR-PHENO','EU-MYO-DX','EU-TICS-DX','EU-CHOREA-DX'))
a+=sec(2,'2. Épidémiologie : le groupe G25 n’a pas une fréquence unique', '''<p>Le tremblement essentiel compte parmi les tremblements les plus fréquents. Il peut commencer jeune, être familial et devenir plus gênant avec l’âge ; le mot « sénile » ne suffit donc pas à le définir. La source suisse USZ, actualisée le 16 avril 2026, décrit cette diversité sans fournir une enquête nationale récente couvrant tous les codes G25.</p><p>Les autres groupes sont très différents. Les myoclonies peuvent être physiologiques à l’endormissement ou révéler une maladie aiguë ou chronique. Les tics ont des profils liés au développement et à leur cause. Le syndrome de la personne raide est rare ; les séries thérapeutiques sont petites. Additionner ces catégories ne donne ni une incidence de maladie unique ni un risque individuel fiable.</p><p>Pour interpréter une fréquence, préciser syndrome, âge, population, méthode de diagnostic et période. Aucun chiffre étranger de tremblement essentiel ou de jambes sans repos n’est présenté ici comme une mesure suisse de l’ensemble de G25. Le retentissement sur les activités et le sommeil guide le besoin de soins au-delà de la fréquence en population.</p>''',('CH-USZ-TREMOR','EU-TREMOR-ET','EU-MYO-DX','EU-TICS-EXAM','EU-SPS-TX'))
a+=sec(3,'3. Physiopathologie : des réseaux et des générateurs différents', '''<p>La commande volontaire et sa régulation mobilisent plusieurs structures nerveuses. Une secousse peut venir d’un générateur cortical, sous-cortical, segmentaire ou périphérique ; son aspect seul ne localise pas toujours ce générateur. Le tremblement se décrit selon ses conditions d’activation et sa cause, sans attribuer tous les syndromes à un déficit dopaminergique unique.</p>'''+figure('basal')+'''<p>La '''+w('positive','myoclonie positive')+''' correspond à une activation musculaire brève ; la '''+w('negative','myoclonie négative')+''' à une interruption brève de l’activité qui maintient une posture. L’astérixis en est un exemple, notamment dans un contexte toxique ou métabolique, sans être le synonyme de toutes les myoclonies négatives.</p><p>Dans les jambes sans repos, la régulation du fer cérébral, la susceptibilité génétique et le système dopaminergique participent à une physiopathologie encore incomplètement connue. Une réponse à un agoniste ne démontre pas un simple manque de dopamine. Dans le '''+w('sps','syndrome de la personne raide')+''', une dysfonction de circuits inhibiteurs, souvent associée à une auto-immunité, offre un mécanisme distinct.</p><p>Au muscle, dépolarisation, calcium et interactions actine-myosine réalisent la contraction. Cette voie finale commune ne rend pas identiques les causes ni les traitements des mouvements observés.</p>''',('EU-MYO-DX','EU-MYO-NEURO','EU-TREMOR-PHENO','EU-RLS-MECH','EU-SPS-MECH','NORMAL-MUSCLE','IMG-BASAL'))
a+=sec(4,'4. Démarche clinique : sécurité, phénomène, cause, décision', '''<ol><li><b>Évaluer la sécurité.</b> Début soudain avec déficit focal, confusion, fièvre, convulsions, trouble respiratoire ou déglutition difficile impose une évaluation urgente.</li><li><b>Observer le phénomène.</b> Oscillation, secousse, interruption de posture, mouvement irrégulier, tic, agitation ou spasme : décrire sans tout appeler tremblement.</li><li><b>Décrire le contexte.</b> Repos, posture, action, station debout, endormissement ou soirée ; chronologie, médicament et signes associés.</li><li><b>Rechercher une cause accessible.</b> Exposition, dérèglement métabolique, lésion, inflammation ou maladie spécifique selon les indices.</li><li><b>Choisir et mesurer.</b> Examen qui change la décision, traitement de la cause et/ou du symptôme, objectifs fonctionnels et suivi.</li></ol><p>La fenêtre '''+w('urgent','urgence et médicaments')+''' relie les signes au circuit de soins. Fièvre, trouble mental et instabilité autonome avec rigidité ou clonus peuvent évoquer une toxicité grave. Une forme atypique de syndrome malin peut être dépourvue de rigidité nette ou n’avoir qu’une fièvre modérée : ne pas attendre tous les signes avant d’agir.</p>''',('CH-PROFILES','EU-MYO-DX','EU-CHOREA-CAUSE','EU-CBIP-URG','FI-TIAPRIDAL','EU-SPS-DX'))
a+=sec(5,'5. Anamnèse : une chronologie observable et les prises réelles', '''<p>Reconstituer première région atteinte, âge de début, installation aiguë, subaiguë ou progressive, fluctuations et retentissement. Demander une '''+w('etiology','histoire étiologique')+''' : maladies rénales, hépatiques, thyroïdiennes, neurologiques ou auto-immunes, événements vasculaires et histoire familiale. Une histoire familiale négative n’exclut pas une cause héréditaire.</p><p>La '''+w('drug','revue médicamenteuse')+''' comprend prescriptions, automédication, traitements reçus ailleurs, changements de dose, arrêts et dernières prises. Neuroleptiques, antiémétiques, agents dopaminergiques, lithium et plusieurs autres produits peuvent contribuer à des mouvements anormaux. Une association temporelle suggère une piste ; elle ne prouve pas toute imputabilité.</p><p>Pour les jambes, préciser gêne sensitive, besoin de bouger, déclenchement au repos, soulagement pendant le mouvement et horaire. Pour les tics, rechercher besoin prémonitoire, suppression transitoire, fluctuations et conséquences scolaires ou sociales, en tenant compte de l’âge. Pour les spasmes, demander douleur, bruit/toucher déclenchants, chutes et raideur axiale.</p><p>Évaluer repas, écriture, marche, travail, sommeil, vigilance et vécu du patient. Une vidéo consentie peut aider si le phénomène est intermittent ; elle complète l’examen et ne le remplace pas.</p>''',('EU-TREMOR-PHENO','EU-CHOREA-DX','EU-CHOREA-CAUSE','EU-RLS-DX','EU-TICS-DX','EU-TICS-EXAM','EU-SPS-DX'))
a+=sec(6,'6. Examen clinique : comparer des conditions sûres', '''<p>Observer au '''+w('rest','repos réellement soutenu')+''', puis en '''+w('posture','maintien de posture')+''' et pendant l’action. Décrire côté, distribution, amplitude, régularité et signes associés. Lors du doigt-nez, une oscillation croissant à l’approche de la cible évoque un '''+w('intention','tremblement d’intention')+''' ; une erreur de visée sans oscillation est une dysmétrie, à décrire séparément.</p>'''+figure('motor')+'''<p>Examiner force, tonus, réflexes, coordination, nerfs crâniens, sensibilité, marche et équilibre. Une secousse distale à l’action, une interruption de maintien ou un mouvement choréique demandent des descriptions différentes. Pour une instabilité uniquement debout, sécuriser l’examen et discuter un enregistrement musculaire dans cette position ; une mesure assise peut manquer le phénomène.</p><p>Le '''+w('functional','tremblement fonctionnel')+''' se recherche par des signes positifs concordants : variabilité, changement avec distraction ou entraînement à une tâche rythmique controlatérale. Aucun de ces signes isolés, une anxiété ou une IRM normale ne suffit. Une maladie neurologique concomitante reste possible, et ce diagnostic n’est pas synonyme de simulation.</p>''',('CH-PROFILES','EU-TREMOR-PHENO','EU-TREMOR-CEREB','EU-TREMOR-FUNC','EU-TREMOR-ORTHO','EU-MYO-NEURO','IMG-MOTOR'))
a+=sec(7,'7. Syndromes : reconnaître les familles sans les fusionner',table(['Phénomène','Description utile','Question suivante'],[['Tremblement','Oscillation rythmique : repos, posture, action, intention ou debout','Quel syndrome, quels signes associés et quelle cause ?'],['Myoclonie','Secousse positive ou interruption négative, parfois sensible aux stimuli','Début aigu ? Générateur ? Épilepsie associée ou cause toxique/métabolique ?'],['Chorée','Mouvements irréguliers, imprévisibles, pouvant se fondre dans le geste','Cause acquise, médicament ou hérédité ? Frontières G10/I02 ?'],['Tic','Mouvement ou vocalisation récurrente, besoin/suppression souvent présents mais variables','Développement, retentissement, cause acquise ou trouble classé F95 ?'],['Akathisie','Agitation et besoin de bouger, difficulté à rester immobile','Médicament, temporalité ; distinguer jambes sans repos et anxiété'],['Jambes sans repos','Besoin de bouger au repos, soulagement par mouvement, prédominance soir/nuit','Les cinq critères sont-ils remplis, avec exclusion des imitateurs ?'],['Personne raide','Raideur axiale/proximale et spasmes déclenchés, marche/chutes','Évaluation neurologique, électrophysiologie, auto-immunité et diagnostics concurrents']])+'''<p>Le tremblement '''+w('orthostatic','orthostatique primaire')+''' est une forme particulière documentée par électromyographie debout, typiquement 13–18 Hz avec forte cohérence. La '''+w('frequency','fréquence')+''' d’un tremblement ordinaire, seule, ne permet pas de conclure à une cause. L’''' +w('akathisia','akathisie')+''' et les '''+w('plms','mouvements périodiques pendant le sommeil')+''' ne se confondent pas avec une envie de bouger définissant le syndrome des jambes sans repos.</p>''',('EU-TREMOR-PHENO','EU-TREMOR-ORTHO','EU-MYO-DX','EU-CHOREA-DX','EU-TICS-DX','EU-CBIP-AKA','EU-RLS-DX','EU-SPS-DX'))
a+=sec(8,'8. Diagnostic positif : critères formels et limites', '''<p>Le '''+w('essential','tremblement essentiel')+''' est défini dans la recommandation DGN/SNG 2022 par un tremblement d’action bilatéral des membres supérieurs depuis au moins trois ans, sans autre syndrome neurologique défini. Des signes discrets peuvent relever de la catégorie '''+w('etplus','essentiel plus')+'''. Un début plus récent exige recherche de cause et réévaluation ; il n’impose pas trois ans d’attente sans soins. Famille atteinte et amélioration après alcool ne sont pas obligatoires, et l’alcool n’est pas un traitement conseillé.</p><p>Pour les '''+w('rls','jambes sans repos')+''', <b>les cinq critères</b> sont requis : besoin de bouger ; début/aggravation au repos ; soulagement partiel ou total par mouvement tant qu’il continue ; prédominance soir/nuit ; manifestations non entièrement expliquées par une autre condition. La fenêtre '''+w('criteria','critères et imitateurs')+''' précise leur application. Le diagnostic est clinique ; une polysomnographie n’est pas systématiquement nécessaire.</p><p>Une '''+w('chorea','chorée')+''' ou un '''+w('tic','tic')+''' se reconnaît par la phénoménologie, puis se rattache à une cause. Pour les myoclonies, le consensus IAPRD publié dans le numéro de mars 2025 organise axe Ia clinique, Ib neurophysiologique et II étiologique ; seul son résumé primaire a été consulté. Ce cadre ne transforme pas une épilepsie myoclonique en G25.3.</p><p>Dans le syndrome de la personne raide, clinique, électrophysiologie et immunologie s’intègrent en neurologie spécialisée. Un anti-GAD65 positif isolé ne remplace pas ce raisonnement.</p>''',('EU-TREMOR-ET','EU-RLS-DX','EU-RLS-MIMIC','EU-CHOREA-DX','EU-TICS-DX','INT-IAPRD2025','CH-CIM-BOUND','EU-SPS-DX'))
a+=sec(9,'9. Explorations : définir la question avant de commander', '''<p>L’''' +w('emg','électromyographie de surface')+''' caractérise les bouffées musculaires et leur organisation. Un '''+w('eeg','enregistrement couplé EEG–EMG')+''' aide à rechercher une relation corticale, parfois avec rétromoyennage. Durée, rythme et corrélation doivent être interprétés ensemble ; un EEG bref normal ne tranche pas tous les épisodes ni tous les générateurs.</p><p>La biologie cherche une cause selon l’histoire : glycémie, électrolytes, fonction rénale/hépatique ou thyroïdienne, notamment. Dans les jambes sans repos, numération et bilan du fer sont recommandés au diagnostic, au début du traitement et lors d’une aggravation. Une '''+w('ferritin','ferritine')+''' ne se lit pas seule, sans saturation de la transferrine, contexte et unités.</p><p>L’IRM répond à une hypothèse structurale, notamment devant syndrome cérébelleux, chorée ou signes focaux. L’exploration immunologique du syndrome de la personne raide, ou un bilan génétique, est orientée par le phénotype et confiée aux spécialistes appropriés. Un vaste panel sans question expose à des résultats difficiles à interpréter.</p>'''+figure('cereb'),('EU-MYO-NEURO','EU-MYO-DX','EU-CHOREA-DX','EU-CHOREA-CAUSE','EU-RLS-IRON','EU-TREMOR-CEREB','EU-SPS-DX','IMG-CEREB'))
a+=sec(10,'10. Arbre diagnostique et différentiels',table(['Point de départ','Branche utile','Erreur à éviter'],[['Installation soudaine avec déficit ou confusion','Circuit urgent, cause vasculaire/toxique/métabolique selon contexte','Traiter d’emblée comme essentiel chronique'],['Oscillation d’action bilatérale ancienne','Critères essentiel, examen des autres signes, médicaments/thyroïde','Confondre tout tremblement avec Parkinson'],['Secousses brèves, chutes d’objets','Positives/négatives, contexte aigu et EEG–EMG selon besoin','Toute secousse = épilepsie ou tout EEG normal = exclusion'],['Mouvement irrégulier imprévisible','Chorée, médicaments, cause métabolique/structurelle, famille','Huntington obligatoire ou histoire familiale négative rassurante à elle seule'],['Besoin de bouger les jambes','Cinq critères, crampes/neuropathie/claudication/akathisie','Diagnostic sur seul symptôme ou seule polysomnographie'],['Instabilité uniquement debout','Comparer assis/marche, électromyographie debout','Confondre avec jambes sans repos sans horaire ni gêne sensitive'],['Raideur et spasmes déclenchés','Syndrome de la personne raide et concurrents, bilan spécialisé','Anti-GAD seul ou stress comme conclusion étiologique']])+'''<p>Les diagnostics peuvent coexister. Une neuropathie n’exclut pas des jambes sans repos si les symptômes sont distingués ; un trouble fonctionnel n’interdit pas une autre atteinte neurologique. La conclusion doit dire ce qui est démontré, ce qui est probable et ce qui reste à réévaluer.</p>''',('EU-MYO-DX','EU-TREMOR-ET','EU-TREMOR-FUNC','EU-TREMOR-ORTHO','EU-RLS-MIMIC','EU-CHOREA-DX','EU-SPS-DX'))
a+=sec(11,'11. Prise en charge : cause, symptôme, statut suisse', '''<p><b>Cause.</b> Corriger une perturbation métabolique, traiter une affection identifiée ou revoir un médicament avec le prescripteur peut modifier le mouvement. Un arrêt brusque improvisé d’agoniste dopaminergique ou d’antiépileptique expose cependant à des complications ; l’urgence toxique grave relève d’une prise en charge immédiate.</p><p><b>Tremblement essentiel gênant.</b> Propranolol et '''+w('primidone','primidone')+''' sont des options de la recommandation DGN/SNG. Inderal a une indication suisse pour l’essentiel ; Mysoline a une FI d’épilepsie et son usage pour tremblement est hors indication. Les formulations et contre-indications guident le choix. Les techniques spécialisées s’envisagent dans des cas sélectionnés, sans indication automatique pour tous les codes G25.</p><p><b>Jambes sans repos.</b> Rechercher facteurs aggravants, comorbidités et bilan du '''+w('iron','fer')+'''. La recommandation germanophone 2024 propose agoniste non ergot à faible dose ou gabapentinoïde hors indication. Le '''+w('prami','pramipexole immédiat')+''' a sa propre dose RLS. La '''+w('pregabalin','prégabaline')+''' n’a pas d’indication RLS dans la FI suisse lue. Le résumé du consensus italien du 17 octobre 2026 préfère les ligands α2δ pour la plupart des adultes chroniques : il dérive explicitement de recommandations américaines et ne change ni l’AMM ni les précautions suisses. La décision spécialisée explique ces différences.</p><p><b>Myoclonies, tics et chorée.</b> Le générateur, la cause et le retentissement guident les choix. Les indications épilepsie du lévétiracétam ou du clonazépam ne constituent pas des AMM pour toutes les myoclonies non épileptiques. Tiapridal distingue tics sévères et chorée de Huntington ; cette dernière indication ne s’étend pas à toutes les chorées G25.</p><p><b>Personne raide.</b> Traitement symptomatique, prise en charge fonctionnelle et immunothérapie sont individualisés en centre spécialisé. La revue européenne 2025 soutient davantage les immunoglobulines intraveineuses que plusieurs alternatives, avec réponse variable et limites de preuve ; aucun protocole de produit ou de dose n’est inventé ici.</p>''',('EU-CHOREA-CAUSE','EU-CBIP-URG','FI-SIFROL','FI-KEPPRA','FI-INDERAL','FI-MYSOLINE','CH-USZ-TX','EU-RLS-TX','EU-RLS-2026','FI-LYRICA','EU-MYO-TX','FI-RIVOTRIL','FI-TIAPRIDAL','EU-SPS-TX'))
a+=sec(12,'12. Prévention, suivi et pronostic : surveiller le bénéfice et les effets', '''<p>Le '''+w('follow','suivi')+''' compare une tâche reproductible, autonomie, sommeil, douleur, chutes et effets indésirables. L’objectif n’est pas seulement une amplitude moindre : le patient doit pouvoir accomplir les activités importantes avec une tolérance acceptable. Revoir une étiologie ou un syndrome si de nouveaux signes apparaissent.</p><p>Sous dopaminergique pour jambes sans repos, rechercher l’''' +w('augmentation','augmentation')+''' : début plus précoce, propagation à d’autres régions, intensité accrue ou durée d’effet moindre. Ce n’est pas une simple carence de dose. Vérifier fer, diagnostics et conduite spécialisée plutôt qu’escalader automatiquement ; le retrait d’un agoniste chronique augmenté peut nécessiter une diminution très lente.</p><p>Prévenir erreurs de formulation, sédation, chutes et conduite dangereuse. Pramipexole : sommeil subit et pulsions ; prégabaline ou clonazépam : sédation et risque respiratoire accru avec dépresseurs centraux ; primidone : interactions et risque reproductif. Une grossesse, un âge pédiatrique ou une insuffisance rénale impose une vérification propre au produit, sans transposition d’un schéma adulte.</p><p>Le pronostic dépend de la cause et du syndrome. Certaines expositions ou perturbations sont corrigeables ; d’autres situations nécessitent un suivi prolongé. Ni guérison universelle ni évolution à échéance fixe ne peuvent se déduire du code G25.</p>''',('EU-TREMOR-PHENO','EU-RLS-AUG','FI-SIFROL','FI-LYRICA','FI-RIVOTRIL','FI-MYSOLINE','FI-FERINJECT','FI-KEPPRA','EU-MYO-TX','EU-SPS-TX'))
a+=sec(13,'13. Points clés', '''<ul><li>Décrire oscillation, secousse positive/négative, chorée, tic, agitation ou spasme avant d’en chercher la cause.</li><li>Début aigu, déficit, confusion, fièvre ou atteinte respiratoire changent le circuit de soins.</li><li>Tremblement essentiel : critères et durée, sans diagnostic par famille, fréquence ou alcool seuls.</li><li>Jambes sans repos : cinq critères cliniques ; mouvements périodiques du sommeil et maladie PLMD ne sont pas équivalents.</li><li>RLS sous agoniste : penser augmentation et statut sel/base ; forme immédiate et forme retard ne se substituent pas librement.</li><li>G25.3 exclut les épilepsies myocloniques ; G25.5 exclut Huntington et Sydenham.</li><li>Le calcul d’un volume suit une dose déjà choisie pour le produit exact ; il ne choisit pas l’indication.</li><li>Sources et contrôles techniques sont documentés ; auto-relecture IA ne signifie pas validation médicale humaine.</li></ul>''',('CH-CIM-BOUND','EU-TREMOR-ET','EU-RLS-DX','EU-RLS-2026','EU-RLS-AUG','FI-SIFROL','FI-FERINJECT','FI-RIVOTRIL','CH-PROFILES'))
a+=sec(14,'14. Pièges qui changent la conduite', '''<ul><li>Faire de G25 une maladie unique ou coder toute hyperkinésie dans ce groupe.</li><li>Présenter une myoclonie toujours irrégulière, une astérixis comme toutes les myoclonies négatives, ou une fréquence comme diagnostic complet.</li><li>Demander systématiquement polysomnographie, IRM ou panel génétique sans question clinique.</li><li>Assimiler la ferritine sanguine à une mesure directe du fer cérébral ou le seuil RLS à une norme universelle.</li><li>Augmenter sans réévaluation un agoniste alors que les symptômes commencent plus tôt.</li><li>Copier une dose Parkinson, une table rénale étrangère, une dose Huntington ou une indication épilepsie vers tout G25.</li><li>Diviser un comprimé non prévu pour cela ou convertir sel/base sans vérifier la présentation.</li><li>Confondre anti-PCP4 sur une image, anti-GAD65 du patient et preuve suffisante de syndrome de la personne raide.</li><li>Présenter un résumé récent, une page de soins ou une adaptation étrangère comme une nouvelle guideline nationale suisse.</li></ul>'''+trap('Le bon traitement dépend du phénomène, de la cause, de la personne et du produit ; une étiquette seule ne suffit pas.'),('CH-CIM','EU-MYO-DX','EU-TREMOR-PHENO','EU-RLS-DX','EU-RLS-MECH','EU-RLS-AUG','FI-SIFROL','FI-LYRICA','FI-KEPPRA','FI-TIAPRIDAL','IMG-PURKINJE','EU-SPS-DX','EU-RLS-2026'))
a+='</div></div>';save('a',a)
print('G25 : quatorze points monographiques rédigés après Betta réellement passé.')
